window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b7c44da852824bdf"]={"versions": [{"id": "FIG-b7c44da852824bdf", "releases": ["R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-Adaptive-Manifests (Metamodell-Ausschnitt). Das Diagramm definiert das Deployment sicherer Kommunikationsmechanismen auf einer <code>Machine</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>Machine</code>: Modelliert die physische/virtuelle Rechnereinheit; erbt von <code>ARElement</code> und <code>AtpStructureElement</code>.\n</li><li><code>SecureCommunicationDeployment</code>: Abstrakte Basisklasse (kursiv dargestellt); erbt von <code>Identifiable</code>.\n</li><li><code>Machine</code> aggregiert via Komposition (<code>«atpSplitable»</code>) mit der Rolle <code>+secureCommunicationDeployment</code> 0 bis beliebig viele (<code>0..*</code>) Instanzen von <code>SecureCommunicationDeployment</code>.\n</li><li><code>SecOcDeployment</code>: Konkrete Spezialisierung von <code>SecureCommunicationDeployment</code> zur Konfiguration von Secure Onboard Communication (SecOC).\n</li><li><code>TlsDeployment</code>: Konkrete Spezialisierung von <code>SecureCommunicationDeployment</code> zur Konfiguration von Transport Layer Security (TLS).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell-Klassendiagramm ist kein dynamisches Verhalten oder Sequenzablauf dargestellt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Stereotyp <code>«atpSplitable»</code> an der Kompositionsbeziehung ermöglicht es, die Bereitstellungskonfigurationen (<code>SecureCommunicationDeployment</code>) über mehrere ARXML-Dateien bzw. Manifest-Fragmente aufzuteilen. Konkrete Implementierungen müssen entweder <code>SecOcDeployment</code> oder <code>TlsDeployment</code> für die jeweilige Maschine instanziieren.</p>"}, {"id": "FIG-0c479f0ba5b06f33", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-Adaptive-Manifests (Metamodell-Ausschnitt). Das Diagramm definiert das Deployment sicherer Kommunikationsmechanismen auf einer <code>Machine</code> sowie deren Zuordnung zum <code>MachineDesign</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>Machine</code>: Modelliert die Rechnereinheit; erbt von <code>ARElement</code> und <code>AtpStructureElement</code>.\n</li><li><code>MachineDesign</code>: Modelliert den Entwurf der Maschine im System- und Netzwerkkontext; erbt von <code>AtpStructureElement</code> und <code>FibexElement</code>. Enthält das optionale Attribut <code>+ pnResetTimer : TimeValue [0..1]</code>.\n</li><li><code>Machine</code> referenziert über eine gerichtete Assoziation mit der Rolle <code>+machineDesign</code> genau eine (<code>1</code>) Instanz von <code>MachineDesign</code>.\n</li><li><code>SecureCommunicationDeployment</code>: Abstrakte Basisklasse (kursiv dargestellt); erbt von <code>Identifiable</code>.\n</li><li><code>Machine</code> aggregiert via Komposition (<code>«atpSplitable»</code>) mit der Rolle <code>+secureCommunicationDeployment</code> 0 bis beliebig viele (<code>0..*</code>) Instanzen von <code>SecureCommunicationDeployment</code>.\n</li><li><code>SecOcDeployment</code>: Konkrete Spezialisierung von <code>SecureCommunicationDeployment</code> für SecOC.\n</li><li><code>TlsDeployment</code>: Konkrete Spezialisierung von <code>SecureCommunicationDeployment</code> für TLS.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Metamodell-Klassendiagramm ist kein dynamisches Verhalten oder Sequenzablauf dargestellt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Stereotyp <code>«atpSplitable»</code> an der Kompositionsbeziehung ermöglicht es, die Deployment-Beschreibungen über verschiedene ARXML-Dateien zu verteilen. Jede <code>Machine</code> muss genau ein zugehöriges <code>MachineDesign</code> über die Referenz <code>+machineDesign</code> referenzieren, wodurch maschinenbezogene System- und Netzwerkeigenschaften wie optional <code>pnResetTimer</code> für Partial Networking angebunden werden.</p>"}], "trans": [{"from": "FIG-b7c44da852824bdf", "to": "FIG-0c479f0ba5b06f33", "fr": "R17-10_R1.2.0", "tr": "R18-03_R1.4.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Ergänzung der Klasse <code>MachineDesign</code> (Stereotype <code>«AtpStructureElement»</code>, <code>«FibexElement»</code>) mit dem Attribut <code>+ pnResetTimer : TimeValue [0..1]</code>.\n</li><li>Ergänzung einer gerichteten Assoziation von <code>Machine</code> zu <code>MachineDesign</code> mit der Rollenbezeichnung <code>+machineDesign</code> und der Kardinalität <code>1</code>.\n</li></ul>"}]};
